package com.companages.controller; import com.companages.dto.*; import com.companages.dto.NotificationDtos.*; import com.companages.service.NotificationService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping PageResponse<Response> list(@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.list(p);}@GetMapping("/summary") Summary summary(){return service.summary();}@PostMapping("/{id}/read")@ResponseStatus(HttpStatus.NO_CONTENT)void read(@PathVariable Long id){service.read(id);}@PostMapping("/read-all")@ResponseStatus(HttpStatus.NO_CONTENT)void readAll(){service.readAll();}}
